<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { api } from './api'
import { loadChallengeNotes, removeChallengeNoteCache, replaceChallengeNoteCache, type SavedChallengeNote } from './challenge-notes'
import { useAuth } from './stores/auth'

const auth = useAuth()
const profile = ref<any>(auth.user), skills = ref<any[]>([]), challenges = ref<any[]>([])
const range = ref<any>({ metrics: { completed: 0, activeSessions: 0 } })
const notes = ref<SavedChallengeNote[]>([]), selectedNote = ref<SavedChallengeNote>()
const deletingNoteId = ref(''), noteActionMessage = ref(''), loading = ref(true), error = ref('')
const initial = computed(() => profile.value?.username?.trim().slice(0, 1) || '学')
const completed = computed(() => challenges.value.filter(item => item.solved))
const learnedSkills = computed(() => skills.value.filter(item => item.xp > 0))
const levelProgress = computed(() => Math.min(100, Math.max(8, Number(profile.value?.xp ?? 0) % 100)))
const nextChallenge = computed(() => range.value?.tasks?.[0] ?? challenges.value.find(item => !item.solved && item.available !== false))
const categoryNames: Record<string, string> = { WEB: '网页安全', CRYPTO: '密码学', NETWORK: '网络分析', REVERSE: '逆向工程', PWN: '二进制安全' }
function formatDate(value: string) { return new Date(value).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) }
function notePreview(content: string) { const plain = content.replace(/[#>*_`~-]/g, '').replace(/\s+/g, ' ').trim(); return plain.length > 88 ? `${plain.slice(0, 88)}…` : plain }
function closeNote() { selectedNote.value = undefined }
function handleEscape(event: KeyboardEvent) { if(event.key==='Escape') closeNote() }
async function deleteNote(note: SavedChallengeNote) { if(deletingNoteId.value)return; deletingNoteId.value=note.id; noteActionMessage.value=''; try{await api(`/users/me/notes/${note.id}`,{method:'DELETE'});notes.value=notes.value.filter(item=>item.id!==note.id);removeChallengeNoteCache(auth.user?.id??'',note.id);if(selectedNote.value?.id===note.id)closeNote();noteActionMessage.value='笔记已删除'}catch(reason:any){noteActionMessage.value=reason.message||'删除失败，请稍后重试'}finally{deletingNoteId.value=''} }

onMounted(async()=>{const userId=auth.user?.id??'',cachedNotes=loadChallengeNotes(userId);notes.value=cachedNotes;try{const[me,skillRows,challengeRows,overview,remoteNotes]=await Promise.all([api<any>('/users/me'),api<any[]>('/users/me/skills'),api<any[]>('/challenges'),api<any>('/range/overview'),api<SavedChallengeNote[]>('/users/me/notes')]);profile.value=me;skills.value=skillRows;challenges.value=challengeRows;range.value=overview;let noteRows=remoteNotes;const fingerprints=new Set(remoteNotes.map(note=>`${note.slug}\u0000${note.content.trim()}`));const pendingMigration=cachedNotes.filter(note=>!fingerprints.has(`${note.slug}\u0000${note.content.trim()}`));if(pendingMigration.length){const migrations=await Promise.allSettled(pendingMigration.map(note=>api(`/challenges/${note.slug}/notes`,{method:'POST',body:JSON.stringify({content:note.content})})));if(migrations.some(item=>item.status==='fulfilled'))noteRows=await api<SavedChallengeNote[]>('/users/me/notes')}notes.value=noteRows;replaceChallengeNoteCache(userId,noteRows);auth.user=me;sessionStorage.setItem('cq_user',JSON.stringify(me))}catch(reason:any){error.value=reason.message||'个人档案暂时无法加载。'}finally{loading.value=false}window.addEventListener('keydown',handleEscape)})
onUnmounted(()=>window.removeEventListener('keydown',handleEscape))
</script>

<template>
  <section class="profile-page">
    <section class="profile-overview"><header class="profile-hero"><div class="profile-identity"><i>{{initial}}</i><div><span class="eyebrow">PERSONAL CENTER</span><h1>{{profile?.username}}</h1><p>{{profile?.email}}</p><div class="profile-badges"><span>CTF 学员</span><span><i></i>在线</span></div></div></div><div class="profile-level"><span>成长等级</span><b>LV.{{profile?.level??1}}</b><i><em :style="{width:`${levelProgress}%`}"></em></i><small>{{profile?.xp??0}} XP</small></div></header><section class="profile-stats" :class="{loading}"><article><span>可用积分</span><b>{{profile?.score??0}}</b><small>解锁官方题解</small></article><article><span>已完成</span><b>{{range.metrics?.completed??completed.length}}</b><small>通过 Flag 验证</small></article><article><span>能力方向</span><b>{{learnedSkills.length}}</b><small>已获得经验</small></article><article><span>题目笔记</span><b>{{notes.length}}</b><small>当前账号记录</small></article></section></section>
    <p v-if="error&&!memoModal" class="profile-error">{{error}}</p>
    <div class="profile-layout"><div class="profile-main-column">
      <section class="profile-notes"><header><div><span class="eyebrow">CHALLENGE NOTES</span><h2>我的题目笔记</h2><p>在题目工作台点击“保存笔记”后，会按当前账号汇总到这里。</p></div><span>{{notes.length}} 篇</span></header><p v-if="noteActionMessage" class="note-action-message">{{noteActionMessage}}</p><div v-if="notes.length" class="profile-note-list"><article v-for="note in notes" :key="note.id"><button class="note-open" @click="selectedNote=note"><span class="note-category">{{note.category}}</span><div><h3>{{note.challengeTitle}}</h3><p>{{notePreview(note.content)}}</p><small>保存于 {{formatDate(note.updatedAt)}}</small></div></button><button class="note-delete" :disabled="deletingNoteId===note.id" aria-label="删除这篇笔记" @click.stop="deleteNote(note)">×</button></article></div><div v-else class="profile-empty"><i>✎</i><b>从第一篇解题笔记开始</b><p>记录关键请求、失败尝试和 Flag 推导过程，保存后会自动归档到这里。</p><div class="profile-empty-steps"><span><em>01</em>进入靶场题目</span><span><em>02</em>记录解题证据</span><span><em>03</em>保存并回看</span></div><RouterLink to="/challenges">选择一道题目开始 →</RouterLink></div></section>
      <section v-if="nextChallenge" class="profile-next"><div class="profile-next-index"><span>NEXT</span><b>01</b></div><div class="profile-next-copy"><span class="eyebrow">CONTINUE TRAINING / 继续训练</span><h2>{{nextChallenge.title}}</h2><p>{{nextChallenge.description}}</p><div><i>{{categoryNames[nextChallenge.category]??nextChallenge.category}}</i><i>{{nextChallenge.difficulty}}</i><i v-for="tag in nextChallenge.tags?.slice(0,2)" :key="tag">{{tag}}</i></div></div><aside><b>{{nextChallenge.points}}</b><span>积分</span><RouterLink :to="`/challenges/${nextChallenge.slug}`">进入工作台 <i>→</i></RouterLink></aside></section>
    </div><aside class="profile-side"><section class="profile-skills"><header><span class="eyebrow">SKILL PROGRESS</span><h2>能力进度</h2></header><div v-for="item in skills" :key="item.skill.slug"><p><b>{{item.skill.name}}</b><span>{{item.xp}} XP</span></p><i><em :style="{width:`${Math.min(100,item.xp)}%`}"></em></i></div></section><section class="profile-completed"><header><span class="eyebrow">SOLVED</span><h2>最近完成</h2></header><RouterLink v-for="item in completed.slice(0,4)" :key="item.slug" :to="`/challenges/${item.slug}`"><i>✓</i><span><b>{{item.title}}</b><small>{{item.points}} 积分 · {{item.category}}</small></span><em>→</em></RouterLink><p v-if="!completed.length">完成第一道题后，这里会形成你的解题档案。</p></section><section class="profile-storage"><b>账号数据说明</b><p>积分、完成记录、题目笔记与日历备忘均按账号持久化在后端。</p></section></aside></div>
    <div v-if="selectedNote" class="note-modal" @click.self="closeNote"><article role="dialog" aria-modal="true"><header><div><span class="eyebrow">NOTE RECORD / 笔记记录</span><h2>{{selectedNote.challengeTitle}}</h2><p>{{categoryNames[selectedNote.category]??selectedNote.category}} · 保存于 {{formatDate(selectedNote.updatedAt)}}</p></div><button @click="closeNote">×</button></header><pre>{{selectedNote.content}}</pre><footer><button class="danger" :disabled="deletingNoteId===selectedNote.id" @click="deleteNote(selectedNote)">删除这篇笔记</button><RouterLink :to="`/challenges/${selectedNote.slug}`">返回题目工作台 →</RouterLink></footer></article></div>
  </section>
</template>
